def g(p,w):
    return p[3]+p[4]*t+p[5]*np.log(t)+p[6]*np.exp(-t)+p[7]*np.sin(w*t)+p[8]*np.cos(w*t)
def model(p):
    return p[0]*t + p[1]*P*np.log(P) + g(p,p[2])/P
